// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title BalanceKeeper
 * @notice ERC20 token that tracks mining rewards for Hash Layer
 * @dev This contract implements ERC20 standard, allowing mined tokens to be transferred,
 *      traded, and used in DeFi protocols. Only HashLayer can mint new tokens.
 */
contract BalanceKeeper is ERC20 {
    address public hashLayer;

    event BalanceAdded(address indexed miner, uint256 amount);

    modifier onlyHashLayer() {
        require(msg.sender == hashLayer, "Only HashLayer can call");
        _;
    }

    /**
     * @notice Constructor sets token name and symbol
     * @param name Token name (e.g., "Hash Layer Token")
     * @param symbol Token symbol (e.g., "HASH")
     */
    constructor(string memory name, string memory symbol) ERC20(name, symbol) {
        // hashLayer will be set after HashLayer deployment
    }
    
    /**
     * @notice Set the HashLayer contract address (can only be called once)
     */
    function setHashLayer(address _hashLayer) external {
        require(hashLayer == address(0), "HashLayer already set");
        require(_hashLayer != address(0), "Invalid address");
        hashLayer = _hashLayer;
    }

    /**
     * @notice Add balance to a miner (only callable by HashLayer)
     * @dev Mints new ERC20 tokens to the miner address
     * @param miner Address of the miner receiving the reward
     * @param amount Amount of tokens to mint (in token units, e.g., 1e18 for 1 token)
     */
    function addBalance(address miner, uint256 amount) external onlyHashLayer {
        _mint(miner, amount);
        emit BalanceAdded(miner, amount);
    }

    /**
     * @notice Get balance of a miner
     * @dev This is equivalent to ERC20 balanceOf, maintained for backward compatibility
     * @param miner Address to check balance for
     * @return Balance of the miner
     */
    function getBalance(address miner) external view returns (uint256) {
        return balanceOf(miner);
    }
}

