// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ChainState
 * @notice Manages the state of the Hash Layer chain (difficulty, last block, reward)
 */
contract ChainState {
    struct BlockHeader {
        uint64 height;
        bytes32 previousHash;
        uint64 nonce;
        bytes data;
    }

    struct Block {
        BlockHeader header;
        bytes32 blockHash;
    }

    struct ChainStateData {
        uint256 difficulty;
        uint64 lastAdjustmentTime;
        Block lastBlock;
        uint256 reward;
    }

    ChainStateData public chainState;
    address public hashLayer;

    event ChainStateUpdated(
        uint64 indexed height,
        bytes32 indexed blockHash,
        uint256 difficulty,
        uint256 reward
    );

    modifier onlyHashLayer() {
        require(msg.sender == hashLayer, "Only HashLayer can call");
        _;
    }

    constructor(
        uint256 initialDifficulty,
        bytes32 genesisHash,
        uint256 initialReward
    ) {
        // hashLayer will be set after HashLayer deployment
        
        BlockHeader memory genesisHeader = BlockHeader({
            height: 0,
            previousHash: bytes32(0),
            nonce: 0,
            data: ""
        });
        
        Block memory genesisBlock = Block({
            header: genesisHeader,
            blockHash: genesisHash
        });
        
        chainState = ChainStateData({
            difficulty: initialDifficulty,
            lastAdjustmentTime: uint64(block.timestamp),
            lastBlock: genesisBlock,
            reward: initialReward
        });
    }

    /**
     * @notice Update the chain state (only callable by HashLayer)
     */
    function updateChainState(
        uint256 newDifficulty,
        Block memory newBlock,
        uint256 newReward
    ) external onlyHashLayer {
        chainState.difficulty = newDifficulty;
        chainState.lastAdjustmentTime = uint64(block.timestamp);
        chainState.lastBlock = newBlock;
        chainState.reward = newReward;

        emit ChainStateUpdated(
            newBlock.header.height,
            newBlock.blockHash,
            newDifficulty,
            newReward
        );
    }

    /**
     * @notice Set the HashLayer contract address (can only be called once)
     */
    function setHashLayer(address _hashLayer) external {
        require(hashLayer == address(0), "HashLayer already set");
        require(_hashLayer != address(0), "Invalid address");
        hashLayer = _hashLayer;
    }

    /**
     * @notice Get the current chain state
     */
    function getChainState()
        external
        view
        returns (ChainStateData memory)
    {
        return chainState;
    }
}

