// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./ChainState.sol";
import "./BalanceKeeper.sol";

/**
 * @title HashLayer
 * @notice Main contract for Hash Layer protocol - permissionless Proof-of-Work layer
 */
contract HashLayer {
    ChainState public immutable chainState;
    BalanceKeeper public immutable balanceKeeper;

    // Block creation event

    event BlockCreated(
        uint64 indexed height,
        bytes32 indexed blockHash,
        bytes32 previousHash,
        uint64 nonce,
        bytes data,
        address indexed miner,
        uint256 reward
    );

    // Mint event
    event CoinsMinted(
        address indexed controller,
        address indexed keeper,
