    );

    constructor(address _chainState, address _balanceKeeper) {
        chainState = ChainState(_chainState);
        balanceKeeper = BalanceKeeper(_balanceKeeper);
    }

    /**
     * @notice Create a new block if the proof of work is valid
     * @param nonce The nonce that satisfies the difficulty requirement
     * @param data Optional data to include in the block
     * @param chainId Address of the chain state contract (for multi-chain support)
     * @param keeper Address of the balance keeper contract
     */
    function createBlock(
        uint64 nonce,
        bytes memory data,
        bytes memory /* imageUrl */,
        address chainId,
        address keeper
    ) external {
        require(address(chainState) == chainId, "Invalid chainId");
        require(address(balanceKeeper) == keeper, "Invalid keeper");

        ChainState.ChainStateData memory state = chainState.getChainState();

        // Calculate the new block height
        uint64 newHeight = state.lastBlock.header.height + 1;

        // Calculate block hash using CPU-friendly algorithm (matches miner)
        bytes32 blockHash = calculateBlockHash(
            newHeight,
            state.lastBlock.blockHash,
            nonce,
            data
        );

        // Verify proof of work
        require(
            verifyProofOfWork(blockHash, state.difficulty),
            "Invalid proof of work"
        );

        // Update chain state
        ChainState.BlockHeader memory newHeader = ChainState.BlockHeader({
            height: newHeight,
            previousHash: state.lastBlock.blockHash,
            nonce: nonce,
            data: data
        });

        ChainState.Block memory newBlock = ChainState.Block({
            header: newHeader,
            blockHash: blockHash
        });

        // Check if difficulty adjustment is needed (every 1440 blocks)
        uint256 newDifficulty = state.difficulty;
        uint256 newReward = state.reward;

        if (newHeight % 1440 == 0) {
            // Difficulty adjustment logic can be added here
            // For now, we keep the same difficulty
        }

        // Update chain state
        chainState.updateChainState(newDifficulty, newBlock, newReward);

        // Award miner
        balanceKeeper.addBalance(msg.sender, newReward);

        // Emit event
        emit BlockCreated(
            newHeight,
            blockHash,
            state.lastBlock.blockHash,
            nonce,
            data,
            msg.sender,
            newReward
        );
    }

    /**
     * @notice Mint coins for a miner based on their balance
     * @param controller Mining controller address
     * @param keeper Balance keeper address
     */
    function mint(address controller, address keeper) external {
        require(address(balanceKeeper) == keeper, "Invalid keeper");
        // Implementation depends on your token contract
        // This is a placeholder
        emit CoinsMinted(controller, keeper, 0);
    }

    /**
     * @notice Get the current chain state
     * @param chainId Address of the chain state contract
     * @return ChainStateData struct containing difficulty, lastBlock, reward, etc.
     */
    function getChainState(
        address chainId
    ) external view returns (ChainState.ChainStateData memory) {
        require(address(chainState) == chainId, "Invalid chainId");
        return chainState.getChainState();
    }

    /**
     * @notice Get the chain object address (same as chainId for EVM)
     * @param chainId Address of the chain state contract
     * @return The chain object address
     */
    function getChainObject(address chainId) external pure returns (address) {
        return chainId;
    }

    /**
     * @notice Get the contract version
     * @return The version number (1)
     */
    function version() external pure returns (uint256) {
        return 2;
    }

    // CPU-friendly algorithm parameters (must match miner)
    // Reduced for gas efficiency while maintaining GPU/ASIC resistance
    uint256 private constant MEMORY_SIZE = 128; // 128 * 32 bytes = 4KB memory
    uint256 private constant ROUNDS = 3; // Number of hash rounds

    /**
     * @notice Calculate block hash using CPU-friendly algorithm (CPUHash)
     * @dev Must match miner's calculation exactly
     *
     * CPU-friendly algorithm:
     * 1. Create initial hash from block data
     * 2. Fill memory buffer sequentially using round-robin hashing
     * 3. Mix memory buffer through multiple rounds
     * 4. Final hash from mixed buffer
     *
     * @param height Block height
     * @param previousHash Previous block hash
     * @param nonce Block nonce
     * @param data Block data
     * @return blockHash The calculated block hash
     */
    function calculateBlockHash(
        uint64 height,
        bytes32 previousHash,
        uint64 nonce,
        bytes memory data
    ) public pure returns (bytes32) {
        // Step 1: Create initial hash from block data
        bytes32 currentHash = keccak256(
            abi.encodePacked(height, previousHash, nonce, data)
        );

        // Step 2: Allocate memory buffer (MEMORY_SIZE * 32 bytes)
        bytes32[MEMORY_SIZE] memory memoryBuffer;

        // Step 3: Fill memory buffer sequentially (memory-hard, sequential access)
        for (uint256 i = 0; i < MEMORY_SIZE; i++) {
            // Each memory slot depends on previous hash + index
            // Pack: hash (32 bytes) + index as little-endian uint32 (4 bytes)
            // Convert index to bytes4 in little-endian format
            bytes4 indexBytesLE;
            assembly {
                // Store i as little-endian uint32 in bytes4
                let idx := i
                indexBytesLE := or(
                    or(
                        or(
                            shl(24, and(idx, 0xFF)), // byte 0 -> position 3
                            shl(16, and(shr(8, idx), 0xFF)) // byte 1 -> position 2
                        ),
                        shl(8, and(shr(16, idx), 0xFF)) // byte 2 -> position 1
                    ),
                    and(shr(24, idx), 0xFF) // byte 3 -> position 0
                )
            }

            bytes memory mixData = abi.encodePacked(currentHash, indexBytesLE);

            // Hash and store in memory buffer
            currentHash = keccak256(mixData);
            memoryBuffer[i] = currentHash;
        }

        // Step 4: Mix memory through multiple rounds (sequential dependencies)
        for (uint256 round = 0; round < ROUNDS; round++) {
            for (uint256 i = 0; i < MEMORY_SIZE; i++) {
                // Mix with previous slot (creates sequential dependency)
                uint256 prevIdx = i > 0 ? i - 1 : MEMORY_SIZE - 1;
                bytes memory mixData = abi.encodePacked(
                    memoryBuffer[i],
                    memoryBuffer[prevIdx]
                );

                // Update memory slot with mixed hash
                memoryBuffer[i] = keccak256(mixData);
            }
        }

        // Step 5: Final hash from entire memory buffer
        // Pack all memory slots into a single bytes array
        bytes memory finalData;
        for (uint256 i = 0; i < MEMORY_SIZE; i++) {
            finalData = abi.encodePacked(finalData, memoryBuffer[i]);
        }

        return keccak256(finalData);
    }

    /**
     * @notice Verify proof of work by checking leading zero bits
     * @param hash The block hash to verify
     * @param difficulty Number of leading zero bits required
     * @return valid Whether the hash satisfies the difficulty requirement
     */
    function verifyProofOfWork(
        bytes32 hash,
        uint256 difficulty
    ) public pure returns (bool) {
        if (difficulty == 0) return true;
        if (difficulty > 256) return false;

        // Calculate how many full bytes must be zero
        uint256 fullZeroBytes = difficulty / 8;

        // Check full zero bytes
        for (uint256 i = 0; i < fullZeroBytes && i < 32; i++) {
            if (uint8(hash[i]) != 0) {
                return false;
            }
        }

        // Check partial bits in the next byte
        uint256 partialBits = difficulty % 8;
        if (partialBits > 0 && fullZeroBytes < 32) {
            uint8 byteValue = uint8(hash[fullZeroBytes]);
            uint8 mask = uint8((0xFF << (8 - partialBits)) & 0xFF);
            if ((byteValue & mask) != 0) {
                return false;
            }
        }

        return true;
    }
}

